// Seleccionamos un producto al azar para publicar hoy
const products = $input.all().map(item => item.json);
if (!products || products.length === 0) {
  throw new Error("No hay productos en el Bazar");
}

// Filtramos productos que tengan precio válido e imagen
const valid = products.filter(p => p.price > 0 && p.imageUrl);
if (valid.length === 0) {
  throw new Error("No hay productos válidos con precio/imagen");
}

// Escoger uno al azar
const randomIndex = Math.floor(Math.random() * valid.length);
const selected = valid[randomIndex];

return [{ json: selected }];

