const product = $('Pick Random Product').first().json;
const geminiRes = $input.all()[0].json;
const directUrl = "https://shongyi.com/bazar?p=" + (product.externalId || product.id);

let postText = geminiRes.candidates?.[0]?.content?.parts?.[0]?.text || "";
if (!postText) {
  postText = `✨ ¡Descubre "${product.title}" en El Rincón de Brandy! ✨\n\n${product.description || ''}\n\n✅ Pieza física lista para usar\n🎨 Personalizable en tu color favorito\n💰 Desde solo $${product.price} MXN\n\n👉 Pídelo directo aquí: ${directUrl}\n\n#ElRinconDeBrandy #Bazar #Gadgets`;
} else {
  // Asegurar que el post contenga el link directo limpio
  postText = postText.replace(/https?:\/\/(?:www\.)?shongyi\.com\/bazar(?:\?p=[a-zA-Z0-9_-]+)?[!.?,;:)"]*/gi, directUrl);
  if (!postText.includes(directUrl)) {
    postText += `\n\n👉 ¡Pídelo directo aquí!: ${directUrl}`;
  }
}

return [{
  json: {
    message: postText,
    link: directUrl,
    imageUrl: product.imageUrl
  }
}];
